with e as (select $1::jsonb j), tel as (select coalesce(nullif(e.j->>'telefone',''), (select w.telefone from wa_identidades w where nullif(e.j->>'lid','') is not null and w.lid = e.j->>'lid' limit 1)) as telefone from e), ident as (insert into wa_identidades (telefone, lid, fonte) select e.j->>'telefone', e.j->>'lid', 'samuel' from e where nullif(e.j->>'lid','') is not null and nullif(e.j->>'telefone','') is not null on conflict (lid) where lid is not null do update set telefone = excluded.telefone, atualizado_em = now() returning 1), velhos as (update serena_wpp_buffer b set processado = true, processado_em = now() from tel t where b.telefone = t.telefone and b.processado = false and b.criado_em < now() - interval '2 minutes' returning b.id), ins as (insert into serena_wpp_buffer (msg_id, telefone, nome, texto) select nullif(e.j->>'msg_id',''), t.telefone, nullif(e.j->>'nome',''), e.j->>'texto' from e, tel t where t.telefone is not null on conflict (msg_id) do nothing returning id, telefone, texto, nome), cfg as (select chave, valor from serena_config where chave like 'wpp_%' or chave = 'antispam') select ins.id as buffer_id, ins.telefone, ins.texto, ins.nome, coalesce(e.j->>'tipo', 'texto') as tipo, coalesce((select valor from cfg where chave = 'wpp_modo'), 'teste') as modo, coalesce((select valor from cfg where chave = 'wpp_teste_numeros'), '') as teste_numeros, coalesce((select valor from cfg where chave = 'wpp_max_por_hora'), '30')::int as max_por_hora, coalesce((select valor from cfg where chave = 'wpp_ignorar_regex'), '') as ignorar_regex, coalesce((select valor from cfg where chave = 'wpp_debounce_seg'), '8')::int as debounce_seg, coalesce((select valor from cfg where chave = 'wpp_ack_rapido'), 'off') as ack_rapido, coalesce((select valor from cfg where chave = 'wpp_ack_regex'), '') as ack_regex, coalesce((select valor from cfg where chave = 'wpp_ack_texto'), 'Só um instante, já estou verificando isso pra você 🙂') as ack_texto, coalesce((select valor from cfg where chave = 'wpp_audio_resposta'), 'off') as audio_resposta, coalesce((select valor from cfg where chave = 'wpp_voz_id'), '') as voz_id, (select count(*) from serena_wpp_buffer b2 where b2.telefone = ins.telefone and b2.processado = false and b2.id < ins.id)::int as pendentes_antes, (select max(m.criado_em) from serena_mensagens m join serena_contatos c on c.id = m.contato_id where c.telefone = '+' || ins.telefone and m.papel in ('serena', 'humano')) as ultima_resposta_em, (select p.ate from serena_wpp_pausas p where p.telefone = ins.telefone and p.ate > now()) as pausada_ate, (select exists(select 1 from serena_wpp_bloqueados b where b.telefone = ins.telefone or b.telefone = (case when length(ins.telefone) = 13 then regexp_replace(ins.telefone, '^(55\d{2})9', '\1') else ins.telefone end) or (case when length(b.telefone) = 13 then regexp_replace(b.telefone, '^(55\d{2})9', '\1') else b.telefone end) = ins.telefone)) as bloqueado, (select count(*) from serena_mensagens m join serena_contatos c on c.id = m.contato_id where c.telefone = '+' || ins.telefone and m.papel = 'serena' and m.canal = 'whatsapp' and m.criado_em > now() - interval '1 hour')::int as respostas_1h, coalesce((select valor from cfg where chave = 'antispam'), 'on') as antispam, (select count(*) from serena_mensagens m join serena_contatos c on c.id = m.contato_id where c.telefone = '+' || ins.telefone)::int as msgs_anteriores, exists(select 1 from scheduled_messages sm where regexp_replace(coalesce(sm.phone, ''), '\D', '', 'g') = ins.telefone) as cliente_conhecido from ins, e
